import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";
import type { Page } from "@playwright/test";
import { test, expect } from "../../fixtures/test-base";
import { DENSE_WORKLOAD, seedDenseWorkbench } from "../../helpers/dense-workbench-fixture";
import { prepareDenseStream } from "../../helpers/dense-canonical-stream";
import { captureDenseTraffic } from "../../helpers/dense-measurement";
import { loadDenseCold } from "../../helpers/dense-cold-load";
import { hashAssetTree, sha256File, snapshotDatabase } from "../../helpers/dense-snapshot";
import { runDenseInteractions } from "../../helpers/dense-interactions";
import { dwell } from "../../helpers/causal-waits";
import { seedThreadPresentation } from "../task/threads-presentation-helpers";

async function readScroll(page: Page, taskId: string) {
  return page
    .getByTestId(`thread-column-${taskId}`)
    .locator(".chat-message-list")
    .evaluate((el) => ({
      scrollTop: el.scrollTop,
      scrollHeight: el.scrollHeight,
      clientHeight: el.clientHeight,
      bottomDistance: el.scrollHeight - el.scrollTop - el.clientHeight,
      bodyTail: Array.from(el.querySelectorAll("[data-agent-message-body]"))
        .at(-1)
        ?.textContent?.slice(-160),
    }));
}

async function installProbe(page: Page, taskId: string) {
  await page.evaluate((id) => {
    const tile = document.querySelector(`[data-testid="thread-column-${id}"]`)!;
    const transcript = tile.querySelector<HTMLElement>(".chat-message-list")!;
    const records: unknown[] = [];
    let dropped = 0;
    const observe = (event: Event) => {
      if (!tile.contains(event.target as Node)) return;
      if (event.type === "scroll" && event.target !== transcript) return;
      if (records.length >= 1000) {
        dropped++;
        return;
      }
      const wheel = event instanceof WheelEvent ? event : null;
      const hit = wheel ? document.elementFromPoint(wheel.clientX, wheel.clientY) : null;
      records.push({
        at: performance.now(),
        type: event.type,
        trusted: event.isTrusted,
        deltaY: wheel?.deltaY,
        targetTranscript: event.composedPath().includes(transcript),
        hitTranscript: hit ? transcript.contains(hit) : null,
        scrollTop: transcript.scrollTop,
        scrollHeight: transcript.scrollHeight,
        clientHeight: transcript.clientHeight,
        bottomDistance: transcript.scrollHeight - transcript.scrollTop - transcript.clientHeight,
      });
    };
    document.addEventListener("wheel", observe, { capture: true, passive: true });
    document.addEventListener("scroll", observe, { capture: true, passive: true });
    (window as Window & { __scrollFollowDiagnostic?: unknown }).__scrollFollowDiagnostic = {
      collect() {
        document.removeEventListener("wheel", observe, true);
        document.removeEventListener("scroll", observe, true);
        return { records, dropped, transcriptStillConnected: transcript.isConnected };
      },
    };
  }, taskId);
}

async function compareInputs(page: Page, taskId: string, started: number) {
  let interactionFailure: unknown;
  let wheelError: string | undefined;
  let actions: unknown;
  try {
    actions = await runDenseInteractions({
      page,
      taskId,
      started,
      durationMs: DENSE_WORKLOAD.durationMs,
      checkpoint: (value) => {
        interactionFailure = value;
      },
    });
  } catch (error) {
    wheelError = String(error);
  }
  const afterWheel = await readScroll(page, taskId);
  const tile = page.getByTestId(`thread-column-${taskId}`);
  const transcript = tile.locator(".chat-message-list");
  await transcript.hover();
  await expect(tile.locator(".thread-composer-disclosure")).toHaveAttribute("data-state", "open");
  await transcript.hover();
  await page.mouse.wheel(0, -300);
  await expect.poll(async () => (await readScroll(page, taskId)).bottomDistance).toBeGreaterThan(3);
  const beforeButton = await readScroll(page, taskId);
  const buttonStartedMs = performance.now() - started;
  let buttonError: string | undefined;
  try {
    await tile.getByTestId("jump-to-latest-button").click();
    await expect
      .poll(async () => (await readScroll(page, taskId)).bottomDistance)
      .toBeLessThanOrEqual(3);
  } catch (error) {
    buttonError = String(error);
  }
  return {
    actions,
    interactionFailure,
    wheelError,
    afterWheel,
    beforeButton,
    buttonStartedMs,
    buttonFinishedMs: performance.now() - started,
    buttonError,
    afterButton: await readScroll(page, taskId),
  };
}

test("attributes native wheel and explicit live-edge following on both frozen builds", async ({
  browser,
  testPage,
  apiClient: api,
  seedData: seed,
  backend,
}, info) => {
  test.setTimeout(1_800_000);
  expect(DENSE_WORKLOAD).toMatchObject({
    tasks: 1000,
    columns: 30,
    messages: 120,
    durationMs: 60000,
    layout: "columns",
  });
  const baseline = process.env.KANDEV_DENSE_BASELINE_ROOT!;
  expect(baseline).toBeTruthy();
  const root = path.resolve(process.cwd(), "../..");
  const directory = path.join(root, ".kandev/diagnostics/dense-workbench-performance");
  const output = path.join(directory, `scroll-follow-attribution-${Date.now()}.json`);
  const builds = Object.fromEntries(
    Object.entries({ baseline, candidate: root }).map(([arm, location]) => {
      const binary = path.join(location, "apps/backend/bin/kandev");
      const assets = path.join(location, "apps/web/dist");
      return [
        arm,
        { binary, assets, binarySha256: sha256File(binary), assetsSha256: hashAssetTree(assets) },
      ];
    }),
  );
  const fixture = await seedDenseWorkbench(api, seed, true);
  await seedThreadPresentation(api, { layout: "columns", maxChats: null, autoHideComposer: true });
  await testPage.close();
  const snapshot = path.join(backend.tmpDir, "scroll-follow-base.db");
  snapshotDatabase(path.join(backend.tmpDir, "kandev.db"), snapshot);
  const report = {
    measurementKind: "scroll-attribution, excluded from speed comparisons",
    instrumentation:
      "Passive wheel/scroll listeners read geometry. Diagnostic overhead is present.",
    sourceRevision: execFileSync("git", ["rev-parse", "HEAD"], {
      encoding: "utf8",
      cwd: root,
    }).trim(),
    sourceSha256: sha256File(info.file),
    builds,
    workload: DENSE_WORKLOAD,
    databaseSha256: sha256File(snapshot),
    fixtureManifest: fixture.manifest,
    samples: [] as Array<Record<string, unknown>>,
    error: undefined as string | undefined,
  };
  const save = () => fs.writeFileSync(output, JSON.stringify(report, null, 2));
  save();
  try {
    for (const arm of ["baseline", "candidate"]) {
      const database = path.join(backend.tmpDir, `scroll-follow-${arm}.db`);
      fs.copyFileSync(snapshot, database);
      expect(sha256File(database)).toBe(report.databaseSha256);
      await backend.restart(
        {
          KANDEV_DATABASE_PATH: database,
          KANDEV_HOME_DIR: path.join(backend.tmpDir, `scroll-follow-${arm}-home`),
          KANDEV_WEB_DIST_DIR: builds[arm].assets,
          KANDEV_LOG_LEVEL: "warn",
        },
        builds[arm].binary,
      );
      const threads = fixture.threads.slice(0, 6);
      const stream = await prepareDenseStream(api, seed, backend, threads, `scroll-follow-${arm}`);
      const context = await browser.newContext({
        baseURL: backend.frontendUrl,
        viewport: { width: 1470, height: 956 },
        deviceScaleFactor: 2,
        locale: "en-US",
        reducedMotion: "no-preference",
      });
      const page = await context.newPage();
      const result: Record<string, unknown> = { arm, browser: browser.version() };
      report.samples.push(result);
      save();
      try {
        await page.addInitScript((port) => {
          localStorage.setItem("kandev.onboarding.completed", "true");
          window.__KANDEV_API_PORT = port;
          window.__KANDEV_E2E_EXPOSE_STORE__ = true;
        }, String(backend.port));
        const cold = await loadDenseCold({
          page,
          workspaceId: seed.workspaceId,
          threads,
          warmup: stream.warmup,
          layout: "columns",
          totalColumns: 30,
          traffic: captureDenseTraffic(page),
        });
        const taskId = cold.visibleTaskIds[0];
        result.visibleTaskIds = cold.visibleTaskIds;
        await installProbe(page, taskId);
        const started = performance.now();
        stream.release();
        result.inputs = await compareInputs(page, taskId, started);
        save();
        await dwell(
          Math.max(0, started + DENSE_WORKLOAD.durationMs - performance.now()),
          "clock-separation",
          "retain the full canonical producer window during scroll attribution",
        );
        await stream.waitForVisible(page, cold.visibleTaskIds);
        result.afterStream = await readScroll(page, taskId);
        await stream.verify();
        result.scheduledUpdates = stream.scheduledUpdates;
        result.verificationErrors = stream.verificationErrors;
        result.orderedVerification = "passed";
      } catch (error) {
        result.error = String(error);
      } finally {
        if (!page.isClosed())
          result.events = await page.evaluate(() =>
            (
              window as Window & { __scrollFollowDiagnostic?: { collect: () => unknown } }
            ).__scrollFollowDiagnostic?.collect(),
          );
        save();
        await context.close();
        await stream.finish();
      }
    }
    expect(report.samples).toHaveLength(2);
    for (const result of report.samples) {
      expect(result.error).toBeUndefined();
      expect((result.inputs as { buttonError?: string }).buttonError).toBeUndefined();
      expect(result.orderedVerification).toBe("passed");
    }
  } catch (error) {
    report.error = String(error);
    save();
    throw error;
  } finally {
    const log = path.join(backend.tmpDir, "backend-process.log");
    if (fs.existsSync(log)) fs.copyFileSync(log, output + ".backend.log");
    await info.attach("scroll-follow-attribution", {
      path: output,
      contentType: "application/json",
    });
  }
});
